import {createEditor} from './editor.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=n=>new Date(Number(n/1000000n)).toLocaleString([],{dateStyle:'medium',timeStyle:'short'});
const check=r=>{if('err'in r)throw new Error(r.err);return r.ok;};
const bytes=b=>new Uint8Array(b);
export async function passwordProof(password,salt){
 const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);
 return new Uint8Array(await crypto.subtle.deriveBits({name:'PBKDF2',hash:'SHA-256',salt:bytes(salt),iterations:600000},key,256));
}
export function shareURL(code){const url=new URL(location.href);url.search='';url.hash='/s/'+code;return url.href;}
export async function openShareDialog({api,token,article,revision}){
 const dialog=document.createElement('dialog');dialog.className='share-dialog';dialog.setAttribute('aria-labelledby','shareTitle');
 dialog.innerHTML=`<header class="dialog-heading"><div><p class="eyebrow">EXTERNAL ACCESS</p><h2 id="shareTitle">Share version ${revision}</h2></div><button type="button" id="closeShare" aria-label="Close sharing">Close</button></header><p class="muted">Visitors can read this published version without a company account. Future edits stay internal until you share them.</p><form id="shareForm"><label for="shareName">Link name <span class="muted">· only visible internally</span></label><input id="shareName" maxlength="80" value="Shared version ${revision}" required><div class="share-options"><div><label for="shareExpiry">Link expires</label><select id="shareExpiry"><option value="1">After 1 day</option><option value="7" selected>After 7 days</option><option value="30">After 30 days</option><option value="custom">Custom duration</option><option value="never">Never</option></select></div><div id="customDays" hidden><label for="shareDays">Number of days</label><input id="shareDays" type="number" min="1" max="3650" value="14"></div></div><label class="check"><input id="usePassword" type="checkbox">Require a password</label><div id="passwordOptions" hidden><label for="sharePassword">Password</label><div class="password-row"><input id="sharePassword" type="password" minlength="12" maxlength="128" autocomplete="new-password" aria-describedby="passwordHint"><button type="button" id="showPassword">Show</button></div><p class="muted" id="passwordHint">Use at least 12 characters. Keep a copy: the password cannot be retrieved later. Send it separately from the link.</p></div><p class="share-consequence" id="shareConsequence">Anyone with the link can read version ${revision} for 7 days.</p><label class="check"><input id="shareReviewed" type="checkbox" required>I checked this version for external sharing.</label><button type="submit" id="createShare" class="primary">Create sharing link</button></form><div id="shareNotice" role="status" aria-live="polite"></div><section id="createdLink" hidden><label for="shareAddress">Sharing link</label><div class="copy-row"><input id="shareAddress" readonly spellcheck="false"><button type="button" id="copyCreated">Copy link</button></div></section><section class="existing-shares"><h3>Links for this article</h3><div id="shareList" role="status">Loading links…</div></section><p class="muted fine-print">You can revoke a link at any time. Copies or downloads already made by a recipient cannot be recalled.</p>`;
 document.body.append(dialog);const $=id=>dialog.querySelector('#'+id);let pending=false,attempt=null,alive=true;
 const notice=(text,error=false)=>{if(!alive)return;$('shareNotice').textContent=text;$('shareNotice').classList.toggle('error',error);};
 const close=()=>{if(pending)return;dialog.close();};$('closeShare').onclick=close;
 dialog.addEventListener('cancel',e=>{if(pending)e.preventDefault();});
 dialog.addEventListener('close',()=>{alive=false;dialog.remove();});dialog.showModal();
 const copy=async(code)=>{const url=shareURL(code);$('createdLink').hidden=false;$('shareAddress').value=url;try{await navigator.clipboard.writeText(url);notice('Link copied.');}catch{$('shareAddress').focus();$('shareAddress').select();notice('Select and copy the link above.');}};
 $('copyCreated').onclick=async()=>{try{await navigator.clipboard.writeText($('shareAddress').value);notice('Link copied.');}catch{$('shareAddress').select();notice('Select and copy the link.');}};
 function settings(){attempt=null;const expiry=$('shareExpiry').value,protectedLink=$('usePassword').checked;$('customDays').hidden=expiry!=='custom';$('passwordOptions').hidden=!protectedLink;$('sharePassword').required=protectedLink;$('shareDays').required=expiry==='custom';$('shareConsequence').textContent=`${protectedLink?'People with the link and password':'Anyone with the link'} can read version ${revision} ${expiry==='never'?'until you revoke the link':`for ${expiry==='custom'?$('shareDays').value:expiry} days`}.`;}
 $('shareForm').addEventListener('input',settings);$('shareForm').addEventListener('change',settings);
 $('showPassword').onclick=()=>{const show=$('sharePassword').type==='password';$('sharePassword').type=show?'text':'password';$('showPassword').textContent=show?'Hide':'Show';};
 async function list(){const links=await api.shareLinks(token(),article);if(!alive)return;$('shareList').innerHTML=links.length?[...links].reverse().map(s=>{const expired=s.expiresAt.length&&Number(s.expiresAt[0]/1000000n)<=Date.now(),active=!s.revokedAt.length&&!expired;return `<div class="share-row"><div><strong>${esc(s.name)}</strong><small>Version ${s.revision} · ${s.passwordProtected?'Password required':'Anyone with link'}<br>${s.revokedAt.length?'Revoked':expired?'Expired':s.expiresAt.length?'Expires '+date(s.expiresAt[0]):'No expiry'}</small></div>${active?`<div class="share-actions"><button type="button" data-copy="${s.id}">Copy link</button><button type="button" data-revoke="${s.id}">Revoke</button></div>`:''}</div>`;}).join(''):'<p class="muted">No external links yet. This article is internal.</p>';
  for(const s of links){const cp=dialog.querySelector(`[data-copy="${s.id}"]`),rv=dialog.querySelector(`[data-revoke="${s.id}"]`);if(cp)cp.onclick=()=>copy(s.code);if(rv)rv.onclick=async()=>{if(pending||!confirm(`Revoke “${s.name}”? Visitors will no longer be able to open this link.`))return;pending=true;rv.disabled=true;try{check(await api.revokeShare(token(),s.id));if(!alive)return;$('createdLink').hidden=true;notice('Link revoked.');await list();}catch(e){notice(e.message||'Revocation could not be confirmed. Retry.',true);}finally{pending=false;if(rv.isConnected)rv.disabled=false;}};}
 }
 $('shareForm').onsubmit=async e=>{e.preventDefault();if(pending)return;pending=true;const controls=[...$('shareForm').elements];controls.forEach(el=>el.disabled=true);$('closeShare').disabled=true;notice('Preparing your link…');
  try{if(!attempt){const protectedLink=$('usePassword').checked;let password=[];if(protectedLink){const text=$('sharePassword').value;if(text.length<12||text.length>128)throw new Error('Use a password between 12 and 128 characters.');const salt=crypto.getRandomValues(new Uint8Array(16));const proof=await passwordProof(text,salt);password=[{salt,verifier:new Uint8Array(await crypto.subtle.digest('SHA-256',proof))}];}
    const days=$('shareExpiry').value;attempt={article,revision,name:$('shareName').value,days:days==='never'?[]:[BigInt(days==='custom'?$('shareDays').value:days)],password,requestId:crypto.randomUUID()};}
   const s=check(await api.createShare(token(),attempt));if(!alive)return;$('sharePassword').value='';$('createdLink').hidden=false;$('shareAddress').value=shareURL(s.code);notice('Sharing link created. Copy it when you are ready.');await list();
  }catch(e){notice(e.message||'The result could not be confirmed. Retry with the same settings.',true);}finally{pending=false;if(alive){controls.forEach(el=>el.disabled=false);$('closeShare').disabled=false;}}
 };
 try{await list();}catch{if(alive)$('shareList').textContent='Links could not be loaded. Close and reopen sharing to retry.';}
}

export async function showShared({api,code,root}){
 root.hidden=false;document.title='Shared documentation · Doku';
 root.innerHTML='<header class="public-heading"><img src="./favicon.svg" width="32" height="32" alt=""><strong>Doku</strong><span>Shared documentation</span></header><main id="publicContent" class="public-content"><p role="status">Opening shared document…</p></main>';
 const content=root.querySelector('#publicContent');let editor,poll,checking=false,opened=false;
 const unavailable=(message='This link is unavailable. It may have expired or been revoked. Ask the sender for a new link.')=>{clearInterval(poll);editor?.destroy();editor=null;opened=false;content.innerHTML=`<section class="empty"><h1>Link unavailable</h1><p>${esc(message)}</p><button id="publicRetry">Try again</button></section>`;content.querySelector('button').onclick=()=>location.reload();};
 async function watch(){if(checking||!opened)return;checking=true;try{if(!(await api.sharedInfo(code)).length)unavailable();}catch{unavailable('Access could not be checked. Reopen the link when the connection is available.');}finally{checking=false;}}
 document.addEventListener('visibilitychange',()=>{if(!document.hidden)watch();});
 async function read(proof){const r=await api.readShared(code,proof);if('err'in r){if(r.err.kind==='unavailable'){unavailable();return;}throw new Error(r.err.kind==='rateLimited'?`Too many attempts. Try again in ${r.err.retryAfterSeconds} seconds.`:'That password did not work. Please try again.');}
  const a=r.ok;content.innerHTML=`<div class="public-title"><p class="eyebrow">READ-ONLY · VERSION ${a.revision}</p><h1>${esc(a.title)}</h1><p class="muted">Published ${date(a.publishedAt)}${a.expiresAt.length?' · Link expires '+date(a.expiresAt[0]):''}</p></div><article class="paper"><div id="publicDocument"></div></article><p class="muted fine-print">This is the version the sender shared. Later edits are not included.</p>`;
  editor=createEditor(content.querySelector('#publicDocument'),{content:JSON.parse(a.document),editable:false});opened=true;poll=setInterval(watch,30000);
 }
 try{if(!/^[a-f0-9]{32}$/.test(code))return unavailable();const [info]=await api.sharedInfo(code);if(!info)return unavailable();if(!info.salt.length)return await read(new Uint8Array());
  content.innerHTML='<section class="password-gate panel"><p class="eyebrow">PASSWORD-PROTECTED LINK</p><h1>A document has been shared with you.</h1><p class="muted">Enter the password provided by the sender.</p><form id="unlockForm"><label for="publicPassword">Password</label><input id="publicPassword" type="password" autocomplete="current-password" maxlength="128" required><button class="primary" type="submit">Open document</button></form><p id="unlockStatus" role="alert"></p></section>';
  const form=content.querySelector('form'),input=content.querySelector('input'),button=content.querySelector('button'),status=content.querySelector('#unlockStatus');
  form.onsubmit=async e=>{e.preventDefault();button.disabled=true;input.disabled=true;status.textContent='Opening document…';try{const proof=await passwordProof(input.value,info.salt[0]);input.value='';await read(proof);}catch(e){status.textContent=e.message||'The connection was interrupted. Please retry.';}finally{if(button.isConnected){button.disabled=false;input.disabled=false;input.focus();}}};
 }catch{unavailable('The document could not be opened. Check your connection and try again.');}
}
